mapper.select:
SELECT pp.*, COALESCE(su.nickname, su.username, pp.operator) AS operator FROM pro_work_process pp INNER JOIN pro_work_order wo ON wo.work_order_id = pp.work_order_id LEFT JOIN sys_user su ON su.user_id = pp.operator_user_id
AND wo.assignee_user_id = #{assigneeUserId} AND pp.work_order_id = #{workOrderId}
ORDER BY pp.create_time DESC, pp.process_record_id DESC

SELECT COALESCE(MAX(step_seq), 0)
FROM pro_work_process
WHERE work_order_id = #{workOrderId}
